package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.node.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.fasterxml.jackson.databind.util.RawValue;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class ObjectDeserializer_deserialize_TriageGen1Test {

    private JsonNodeDeserializer.ObjectDeserializer objectDeserializer;

    @Mock
    private JsonParser mockParser;

    @Mock
    private DeserializationContext mockContext;

    @Mock
    private com.fasterxml.jackson.databind.node.JsonNodeFactory mockNodeFactory;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        objectDeserializer = JsonNodeDeserializer.ObjectDeserializer.getInstance();
        when(mockContext.getNodeFactory()).thenReturn(mockNodeFactory);
    }

    @Test
    public void testDeserialize_StartObject() throws IOException {
        // Arrange
        when(mockParser.getCurrentToken()).thenReturn(JsonToken.START_OBJECT);

        // We need to spy on the deserializer to mock the protected deserializeObject method
        // since it is part of the same class and we want to isolate the 'deserialize' logic
        JsonNodeDeserializer.ObjectDeserializer spyDeserializer = spy(objectDeserializer);
        ObjectNode expectedNode = mock(ObjectNode.class);

        doReturn(expectedNode).when(spyDeserializer).deserializeObject(eq(mockParser), eq(mockContext), eq(mockNodeFactory));

        // Act
        ObjectNode result = spyDeserializer.deserialize(mockParser, mockContext);

        // Assert
        assertEquals(expectedNode, result);
        verify(mockParser).nextToken();
        verify(spyDeserializer).deserializeObject(mockParser, mockContext, mockNodeFactory);
    }

    @Test
    public void testDeserialize_FieldName() throws IOException {
        // Arrange
        when(mockParser.getCurrentToken()).thenReturn(JsonToken.FIELD_NAME);

        JsonNodeDeserializer.ObjectDeserializer spyDeserializer = spy(objectDeserializer);
        ObjectNode expectedNode = mock(ObjectNode.class);

        doReturn(expectedNode).when(spyDeserializer).deserializeObject(eq(mockParser), eq(mockContext), eq(mockNodeFactory));

        // Act
        ObjectNode result = spyDeserializer.deserialize(mockParser, mockContext);

        // Assert
        assertEquals(expectedNode, result);
        // Note: for FIELD_NAME, nextToken() is NOT called in the first if block
        verify(mockParser, never()).nextToken();
        verify(spyDeserializer).deserializeObject(mockParser, mockContext, mockNodeFactory);
    }

    @Test(expected = IOException.class)
    public void testDeserialize_ThrowsExceptionOnOtherTokens() throws IOException {
        // Arrange
        // Testing a token that is neither START_OBJECT nor FIELD_NAME (e.g., VALUE_STRING)
        when(mockParser.getCurrentToken()).thenReturn(JsonToken.VALUE_STRING);
        when(mockContext.mappingException(ObjectNode.class)).thenThrow(new IOException("Mapping exception"));

        // Act
        objectDeserializer.deserialize(mockParser, mockContext);

        // Assert handled by expected exception
    }

    @Test
    public void testDeserialize_ThrowsMappingException() throws IOException {
        // Arrange
        when(mockParser.getCurrentToken()).thenReturn(JsonToken.END_OBJECT);
        when(mockContext.mappingException(ObjectNode.class)).thenReturn(new IOException("Mapping exception"));

        // Act & Assert
        try {
            objectDeserializer.deserialize(mockParser, mockContext);
        } catch (IOException e) {
            assertEquals("Mapping exception", e.getMessage());
            verify(mockContext).mappingException(ObjectNode.class);
        }
    }
}
